def anchor(va):
    e=db.execute('select * from functions where va=?',(int(va,16),)).fetchone()
    return f"ArcCore-1.170.0 {va} {e['name']}; {e['path']}@{e['offset']}+{e['length']}"
findings=[]
def finding(severity,cls,sel,claim,vas,exact,correction):
    specs=(SRC/'classes'/f'{cls}.md').read_text().splitlines()
    lines=[str(i) for i,l in enumerate(specs,1) if (f' {sel} |' in l) or (claim in l)]
    evidence=f"specs/classes/{cls}.md lines {','.join(lines) or 'prose'}; "+' ; '.join(anchor(va) for va in vas.split())+'; '+exact
    findings.append(dict(severity=severity,**{'class':cls},selector=sel,claim=claim,**{'exact evidence':evidence},**{'required correction':correction}))
